INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Bahay Bata (Baby Factory)', 'Bahay Bata (Baby Factory)', 'bahay-bata-baby-factory-2011', 'Sarah is a nurse at a Public Maternity Hospital. The hospital is abuzz with pregnant mothers of all shapes and sizes in different stages of labor. The hospital is short on staff on Christmas Day so Sarah is forced to put in a double shift. Sarah observes the women coming and going in her ward, noting who is a first-timer and who is a veteran.', '2011-01-01', 2011, 'assets/factory.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
