INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Niño', 'Niño', 'nino-2011', 'The once-prominent Lopez-Aranda family is falling apart as Celia, a former opera star, struggles with debt and the threat of losing her home while caring for her bedridden ex-husband, Gaspar. When Gaspar falls into a coma and his daughter Raquel returns from the US to sell the house, Celia turns to her faith in the Sto. Niño and hopes for a miracle to save her from homelessness.', '2011-01-01', 2011, 'assets/nino.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
