INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Magkakapatid (Blood Ties)', 'Magkakapatid (Blood Ties)', 'magkakapatid-blood-ties-2010', 'Magkakapatid is a story about a family that drifts apart due to socio-economic differences. Three siblings, three narratives, one tragedy, wherein a brother kills his own brother, a father struggles to accept a daughter’s marriage, and a daughter who could not mourn.', '2010-01-01', 2010, 'assets/magkakapatid.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
