INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Si Techie, Si Teknoboy at Si Juana B.', 'Si Techie, Si Teknoboy at Si Juana B.', 'si-techie-si-teknoboy-at-si-juana-b-2010', 'Techie and Jay, both OFWs from Qatar, decide to come home for two weeks to get married. Unknown to Jay, Techie is nurturing a plan to meet her virtual lover, Teknoboy, before her wedding day.', '2010-01-01', 2010, 'assets/techie.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
