INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Limbunan', 'Limbunan', 'limbunan-2010', 'Limbunan captures the ritual motions of the women in a family preparing for the wedding of seventeen-year-old Ayesah who is betrothed to a man she barely knows. As Maguindanaon tradition dictates, she will be kept from public view in her private quarters—limbunan. As preparations for her union is underway, Ayesah is reunited with her childhood tutor Maguid who returns to the village as a militiaman after five years, reawakening Ayesah’s past memory of childhood infatuation.', '2010-01-01', 2010, 'assets/limbunan.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
